import { FilterDataAccessor } from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
  Option,
} from 'models/Filters';

const EMPTY_FILTER_VALUES = new Set(['', 'ALL', 'All']);

const GLOBAL_GEO_VALUES = new Set(['', 'ABI', 'All', 'ALL']);

export const GEO_ZONE_STEP = '__geo_zone__' as const;
export const GEO_COUNTRY_STEP = '__geo_country__' as const;

export type GeoStepKey = typeof GEO_ZONE_STEP | typeof GEO_COUNTRY_STEP;

export const GEO_STEP_KEYS = new Set<string>([GEO_ZONE_STEP, GEO_COUNTRY_STEP]);

export type GeoAnchorMode = 'global' | 'zone' | 'country' | 'crossPageCountry';

export type GeoAnchor = {
  zone: string;
  country: string;
  rootLabel: string;
  mode: GeoAnchorMode;
};

export function isGeoStepKey(key: string): key is GeoStepKey {
  return GEO_STEP_KEYS.has(key);
}

function isSpecificGeoValue(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (typeof value === 'string') {
    return !GLOBAL_GEO_VALUES.has(value);
  }
  if (typeof value === 'number') {
    return !GLOBAL_GEO_VALUES.has(String(value));
  }
  return false;
}

export function isSpecificCountry(country: unknown): boolean {
  return isSpecificGeoValue(country);
}

export function isSpecificZone(zone: unknown): boolean {
  return isSpecificGeoValue(zone);
}

export function isGeoStepActive(
  key: string,
  applied: FilterForm | undefined,
): boolean {
  if (key === GEO_ZONE_STEP) {
    return isSpecificZone(applied?.zone);
  }

  if (key === GEO_COUNTRY_STEP) {
    return isSpecificCountry(applied?.country);
  }

  return false;
}

export function isGeoAnchorCaptureReady(
  applied: FilterForm,
  urlZone: string | null,
  urlCountry: string | null,
): boolean {
  if (urlZone !== null && isSpecificZone(urlZone)) {
    if (String(applied.zone ?? '') !== urlZone) {
      return false;
    }
  }

  if (
    urlCountry !== null &&
    isSpecificCountry(urlCountry) &&
    String(applied.country ?? '') !== urlCountry
  ) {
    return false;
  }

  return true;
}

export function shouldPreserveAnchorRootLabel(
  anchor: GeoAnchor,
  applied: FilterForm | undefined,
): boolean {
  if (anchor.mode === 'global') {
    return true;
  }

  if (anchor.mode === 'zone') {
    if (!applied) {
      return false;
    }

    return String(applied.zone ?? '') === anchor.zone;
  }

  if (!applied || !isSpecificCountry(applied.country)) {
    return false;
  }

  return String(applied.country) === anchor.country;
}

export function shouldIncludeCountryGeoStepInPath(
  anchor: GeoAnchor | null | undefined,
): boolean {
  if (!anchor) return true;

  return anchor.mode === 'global' || anchor.mode === 'zone';
}

export type DrillDownNavigationChip = {
  label: string;
  key: string;
};

export type BuildDrillDownNavigationPathParams = {
  navigationOrder: readonly string[];
  applied: FilterForm | undefined;
  dataFilters: FilterDataStructure | undefined;
  anchor: GeoAnchor | null | undefined;
  hasSpecificValue: (value: unknown) => boolean;
  accessor?: FilterDataAccessor;
};

function resolveGeoZoneNavigationChip(
  key: string,
  applied: FilterForm | undefined,
  dataFilters: FilterDataStructure | undefined,
  accessor: FilterDataAccessor,
): DrillDownNavigationChip | null {
  const zoneLabel = accessor.getZone(dataFilters ?? {}, applied ?? {})?.label;
  if (!zoneLabel || !isSpecificZone(applied?.zone)) {
    return null;
  }

  return { label: String(zoneLabel), key };
}

function resolveGeoCountryNavigationChip(
  key: string,
  anchor: GeoAnchor | null | undefined,
  applied: FilterForm | undefined,
  dataFilters: FilterDataStructure | undefined,
  accessor: FilterDataAccessor,
): DrillDownNavigationChip | null {
  if (!shouldIncludeCountryGeoStepInPath(anchor)) {
    return null;
  }

  const countryLabel = accessor.getCountry(
    dataFilters ?? {},
    applied ?? {},
  )?.label;
  if (!countryLabel || !isSpecificCountry(applied?.country)) {
    return null;
  }

  return { label: String(countryLabel), key };
}

function resolveFilterNavigationChip(
  key: string,
  applied: FilterForm | undefined,
  hasSpecificValue: (value: unknown) => boolean,
): DrillDownNavigationChip | null {
  const value = applied?.[key];
  if (!hasSpecificValue(value)) {
    return null;
  }

  return { label: String(value), key };
}

function resolveNavigationStepChip(
  key: string,
  params: BuildDrillDownNavigationPathParams,
  accessor: FilterDataAccessor,
): DrillDownNavigationChip | null {
  if (key === GEO_ZONE_STEP) {
    return resolveGeoZoneNavigationChip(
      key,
      params.applied,
      params.dataFilters,
      accessor,
    );
  }

  if (key === GEO_COUNTRY_STEP) {
    return resolveGeoCountryNavigationChip(
      key,
      params.anchor,
      params.applied,
      params.dataFilters,
      accessor,
    );
  }

  return resolveFilterNavigationChip(
    key,
    params.applied,
    params.hasSpecificValue,
  );
}

export function buildDrillDownNavigationPath(
  params: BuildDrillDownNavigationPathParams,
): { path: string[]; pathWithKeys: DrillDownNavigationChip[] } {
  const accessor = params.accessor ?? FilterDataAccessor.getInstance();
  const path: string[] = [];
  const pathWithKeys: DrillDownNavigationChip[] = [];

  for (const key of params.navigationOrder) {
    const chip = resolveNavigationStepChip(key, params, accessor);
    if (!chip) continue;

    path.push(chip.label);
    pathWithKeys.push(chip);
  }

  return { path, pathWithKeys };
}

export function resolveBreadcrumbRootLabel(
  anchor: GeoAnchor | null | undefined,
  applied: FilterForm | undefined,
  dataFilters: FilterDataStructure | undefined,
  accessor: FilterDataAccessor = FilterDataAccessor.getInstance(),
): string {
  if (anchor?.rootLabel && shouldPreserveAnchorRootLabel(anchor, applied)) {
    return anchor.rootLabel;
  }

  if (
    String(applied?.zone ?? '') === 'ABI' &&
    String(applied?.country ?? '') === 'ABI'
  ) {
    return 'Global';
  }

  const countryLabel = accessor.getCountry(
    dataFilters ?? {},
    applied ?? {},
  )?.label;
  if (countryLabel) {
    return countryLabel === 'All' ? 'Global' : String(countryLabel);
  }

  const zoneLabel = accessor.getZone(dataFilters ?? {}, applied ?? {})?.label;
  if (
    zoneLabel &&
    isSpecificZone(applied?.zone) &&
    !isSpecificCountry(applied?.country)
  ) {
    return String(zoneLabel);
  }

  return '';
}

export function deriveEntryGeoAnchor(
  applied: FilterForm | undefined,
  dataFilters: FilterDataStructure | undefined,
  urlCountry: string | null,
  accessor: FilterDataAccessor = FilterDataAccessor.getInstance(),
): GeoAnchor | null {
  if (!applied) return null;

  if (urlCountry && isSpecificCountry(urlCountry)) {
    const countryOption = accessor.getCountry(dataFilters ?? {}, {
      ...applied,
      country: urlCountry,
    });

    return {
      zone: String(applied.zone ?? ''),
      country: urlCountry,
      rootLabel: String(countryOption?.label ?? urlCountry),
      mode: 'crossPageCountry',
    };
  }

  const zone = String(applied.zone ?? '');
  const country = String(applied.country ?? '');
  const zones = accessor.getOptions('zone', dataFilters ?? {}, applied);
  const hasGlobalZoneAccess = (zones as Option[])?.some(
    (zoneOption) => zoneOption.value === 'ABI',
  );

  if (zone === 'ABI' && country === 'ABI') {
    return {
      zone: 'ABI',
      country: 'ABI',
      rootLabel: 'Global',
      mode: 'global',
    };
  }

  if (
    hasGlobalZoneAccess &&
    !isSpecificCountry(country) &&
    !isSpecificZone(zone)
  ) {
    return {
      zone: 'ABI',
      country: 'ABI',
      rootLabel: 'Global',
      mode: 'global',
    };
  }

  if (
    hasGlobalZoneAccess &&
    isSpecificCountry(country) &&
    urlCountry !== null &&
    !isSpecificCountry(urlCountry)
  ) {
    return {
      zone: 'ABI',
      country: 'ABI',
      rootLabel: 'Global',
      mode: 'global',
    };
  }

  if (isSpecificZone(zone) && !isSpecificCountry(country)) {
    const zoneOption = accessor.getZone(dataFilters ?? {}, applied);

    return {
      zone,
      country: country || 'ABI',
      rootLabel: String(zoneOption?.label ?? zone),
      mode: 'zone',
    };
  }

  if (!hasGlobalZoneAccess || isSpecificCountry(country)) {
    const countryOption = accessor.getCountry(dataFilters ?? {}, applied);

    return {
      zone,
      country,
      rootLabel: String(countryOption?.label ?? ''),
      mode: 'country',
    };
  }

  const zoneOption = accessor.getZone(dataFilters ?? {}, applied);

  return {
    zone,
    country,
    rootLabel: String(zoneOption?.label ?? zone),
    mode: 'zone',
  };
}

export function buildGeoRestorePatch(
  keysToKeep: ReadonlySet<string>,
  anchor: GeoAnchor,
): Record<string, FilterValue> {
  const keepsZoneStep = keysToKeep.has(GEO_ZONE_STEP);
  const keepsCountryStep = keysToKeep.has(GEO_COUNTRY_STEP);

  if (!keepsZoneStep && !keepsCountryStep) {
    return {
      zone: anchor.zone,
      country: anchor.country,
    };
  }

  if (keepsZoneStep && !keepsCountryStep) {
    // Zone chip kept: restore zone-level view (country back to global ABI for global users).
    return {
      country: anchor.mode === 'global' ? 'ABI' : anchor.country,
    };
  }

  return {};
}

type GeoFilterDelta = {
  currZone: string;
  currCountry: string;
  zoneDrilled: boolean;
  countryDrilled: boolean;
};

function isFixedCountryAnchorMode(mode: GeoAnchorMode): boolean {
  return mode === 'crossPageCountry' || mode === 'country';
}

function syncGeoStepsForFixedCountryAnchor(
  order: readonly string[],
): string[] | null {
  if (!order.includes(GEO_COUNTRY_STEP)) {
    return null;
  }

  return order.filter((key) => key !== GEO_COUNTRY_STEP);
}

function getGeoFilterDelta(
  prev: FilterForm,
  current: FilterForm,
  anchor: GeoAnchor,
): GeoFilterDelta {
  const prevZone = String(prev.zone ?? '');
  const currZone = String(current.zone ?? '');
  const prevCountry = String(prev.country ?? '');
  const currCountry = String(current.country ?? '');

  return {
    currZone,
    currCountry,
    zoneDrilled:
      currZone !== anchor.zone &&
      isSpecificZone(currZone) &&
      prevZone !== currZone,
    countryDrilled:
      currCountry !== anchor.country &&
      isSpecificCountry(currCountry) &&
      prevCountry !== currCountry,
  };
}

function shouldAppendZoneStep(
  delta: GeoFilterDelta,
  order: readonly string[],
): boolean {
  return (
    delta.zoneDrilled &&
    !isSpecificCountry(delta.currCountry) &&
    delta.currZone === 'EUR' &&
    !order.includes(GEO_ZONE_STEP)
  );
}

function shouldAppendCountryStep(
  delta: GeoFilterDelta,
  order: readonly string[],
): boolean {
  return delta.countryDrilled && !order.includes(GEO_COUNTRY_STEP);
}

function applyGeoStepRemovals(
  order: string[],
  anchor: GeoAnchor,
  currZone: string,
  currCountry: string,
): { next: string[]; changed: boolean } {
  let next = order;
  let changed = false;

  const removeStep = (step: string) => {
    if (!next.includes(step)) {
      return;
    }

    next = next.filter((key) => key !== step);
    changed = true;
  };

  if (anchor.mode === 'zone') {
    const zoneScopeLost = !isSpecificZone(currZone) || currZone !== anchor.zone;

    if (zoneScopeLost) {
      removeStep(GEO_ZONE_STEP);
    }
  }

  if (!isSpecificZone(currZone)) {
    removeStep(GEO_ZONE_STEP);
  }

  if (!isSpecificCountry(currCountry)) {
    removeStep(GEO_COUNTRY_STEP);
  }

  return { next, changed };
}

export function syncGeoNavigationSteps(
  prev: FilterForm,
  current: FilterForm,
  anchor: GeoAnchor,
  order: readonly string[],
): string[] | null {
  if (isFixedCountryAnchorMode(anchor.mode)) {
    return syncGeoStepsForFixedCountryAnchor(order);
  }

  const delta = getGeoFilterDelta(prev, current, anchor);
  let next = [...order];
  let changed = false;

  if (shouldAppendZoneStep(delta, next)) {
    next = [...next, GEO_ZONE_STEP];
    changed = true;
  }

  if (shouldAppendCountryStep(delta, next)) {
    next = [...next, GEO_COUNTRY_STEP];
    changed = true;
  }

  const removal = applyGeoStepRemovals(
    next,
    anchor,
    delta.currZone,
    delta.currCountry,
  );

  if (removal.changed) {
    next = removal.next;
    changed = true;
  }

  return changed ? next : null;
}

export function hasDrillDownSpecificFilterValue(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (typeof value !== 'string') return true;
  return !EMPTY_FILTER_VALUES.has(value);
}

export function buildDefaultDrillDownClearPatch<TKey extends string>(
  defaults: FilterForm | undefined,
  keys: readonly TKey[],
): Record<string, FilterValue> {
  return keys.reduce<Record<string, FilterValue>>((acc, key) => {
    const defaultValue = defaults?.[key] ?? null;
    const clearValue = hasDrillDownSpecificFilterValue(defaultValue)
      ? null
      : defaultValue;

    return { ...acc, [key]: clearValue };
  }, {});
}

export function isAllowedNavigationKey(
  key: string,
  goldenPathOrder: readonly string[],
): boolean {
  return (
    (goldenPathOrder as readonly string[]).includes(key) || isGeoStepKey(key)
  );
}
